@__export('con_uw_master_auction_2')
def auction_thing(contract: str, uid: str, reserve_price: float, start_date:
    datetime.datetime, end_date: datetime.datetime):
    thing_master_contract = I.import_module(contract)
    thing_master_contract.transfer_from(uid, ctx.this, ctx.caller, contract)
    assert not __S[uid], 'Auction has already started!'
    assert end_date > now, 'end_date is in the past'
    assert reserve_price >= 0, 'reserve_price cannot be less than 0'
    __S[uid, 'start_date'] = start_date
    __S[uid, 'end_date'] = end_date
    __S[uid, 'current_owner'] = ctx.caller
    __S[uid, 'uid'] = uid
    __S[uid, 'reserve_price'] = reserve_price
    __S[uid, 'current_bid'] = None
    __S[uid, 'current_winner'] = ''
