@__export('con_uw_master_auction_2')
def end_auction(uid: str, end_early: bool, contract: str):
    listing_info = __get_listing_info(uid=uid)
    if end_early:
        assert listing_info['current_owner'] == ctx.caller or __metadata[
            'operator'
            ] == ctx.caller, 'Only thing owner or auction operator can end the auction early!'
        if now < listing_info['start_date']:
            __process_auction_result_no_winner(listing_info, contract)
        elif (listing_info['current_bid'] or -1) < listing_info['reserve_price'
            ]:
            __process_auction_result_no_winner(listing_info, contract)
        else:
            assert False, 'Cannot end early. Auction started or reserve has been met.'
    else:
        assert now > listing_info['end_date'], 'Auction is still pending!'
        if listing_info['current_bid'] == None or listing_info['current_bid'
            ] < listing_info['reserve_price']:
            __process_auction_result_no_winner(listing_info, contract)
        else:
            __process_auction_result(listing_info, contract)


def __process_auction_result_no_winner(listing_info, contract):
    thing_master_contract = I.import_module(contract)
    thing_master_contract.transfer(uid=listing_info['uid'], new_owner=
        listing_info['current_owner'], contract=contract)
    if listing_info['current_winner'] != '':
        con_uwarriors_lst001.transfer(to=listing_info['current_winner'],
            amount=listing_info['current_bid'])
    __S[listing_info['uid']] = False


def __process_auction_result(listing_info, contract):
    thing_master_contract = I.import_module(contract)
    thing_master_contract.transfer(uid=listing_info['uid'], new_owner=
        listing_info['current_winner'], contract=contract)
    net_amount = listing_info['current_bid']
    con_uwarriors_lst001.transfer(to=listing_info['current_owner'], amount=
        net_amount)
    __S[listing_info['uid']] = False


